import sqlite3
import sys
import re

def parse_filter_clause(clause):
    parts = re.split(r'\s+', clause.strip())
    if len(parts) < 3:
        return None
    column, operator, value = parts[0], parts[1], ' '.join(parts[2:])
    return column, operator, value

def evaluate_expression(formula, id_val, name_val, category_val, amount_val):
    try:
        # Replace variables with their values
        expr = formula.replace('id', str(id_val)).replace('name', name_val).replace('category', category_val).replace('amount', str(amount_val))
        # Evaluate the expression safely
        return eval(expr, {'__builtins__': None}, {'id': id_val, 'name': name_val, 'category': category_val, 'amount': amount_val})
    except:
        return None

def main():
    if len(sys.argv) != 2:
        print("Usage: python filter_records.py <database_file>", file=sys.stderr)
        sys.exit(1)

    db_path = sys.argv[1]
    conn = sqlite3.connect(db_path)
    cursor = conn.cursor()

    filters = []
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        column, operator, value = parse_filter_clause(line)
        if column and operator and value:
            filters.append((column, operator, value))

    if not filters:
        # No filters, query all rows
        cursor.execute("SELECT id, name, category, amount, formula FROM records ORDER BY id ASC")
        rows = cursor.fetchall()
    else:
        # Build WHERE clause dynamically
        where_clauses = []
        for column, operator, value in filters:
            if column == 'id' or column == 'amount':
                # Numeric comparison
                if operator == '=':
                    where_clauses.append(f"{column} = {value}")
                elif operator == '!=':
                    where_clauses.append(f"{column} != {value}")
                elif operator == '<':
                    where_clauses.append(f"{column} < {value}")
                elif operator == '<=':
                    where_clauses.append(f"{column} <= {value}")
                elif operator == '>':
                    where_clauses.append(f"{column} > {value}")
                elif operator == '>=':
                    where_clauses.append(f"{column} >= {value}")
            else:
                # Text comparison
                if operator == '=':
                    where_clauses.append(f"{column} = ?")
                elif operator == '!=':
                    where_clauses.append(f"{column} != ?")
                else:
                    where_clauses.append(f"{column} {operator} ?")

        where_clause = " AND ".join(where_clauses)
        params = []
        for i, (column, _, _) in enumerate(filters):
            if column in ('name', 'category'):
                params.append(value if value == value.replace(' ', '') else f"'{value.replace(' ', '')}'")

        cursor.execute(f"SELECT id, name, category, amount, formula FROM records WHERE {where_clause} ORDER BY id ASC", params)
        rows = cursor.fetchall()

    conn.close()

    for row in rows:
        id_val, name_val, category_val, amount_val, formula = row
        value = evaluate_expression(formula, id_val, name_val, category_val, amount_val)
        if value is not None:
            print(f"{id_val},{name_val},{value:.1f}")

