import sqlite3
import sys
import re
from typing import List, Tuple, Dict, Any

def parse_filter_rule(rule: str) -> Tuple[str, str, Any]:
    parts = rule.split(maxsplit=2)
    if len(parts) != 3:
        raise ValueError(f"Invalid filter rule: '{rule}'")
    column, operator, value_str = parts
    if column not in ('id', 'name', 'category', 'amount'):
        raise ValueError(f"Invalid column: '{column}'")
    if operator not in ('=', '!=', '<', '<=', '>', '>='):
        raise ValueError(f"Invalid operator: '{operator}'")

    try:
        if column in ('id', 'amount'):
            value = int(value_str)
        else:
            value = value_str
    except ValueError:
        raise ValueError(f"Invalid value for column '{column}': '{value_str}'")

    return column, operator, value

def evaluate_expression(formula: str, row: Dict[str, Any]) -> float:
    try:
        # Replace variables with their values
        expr = formula.replace('id', str(row['id']))
        expr = expr.replace('name', repr(row['name']))
        expr = expr.replace('category', repr(row['category']))
        expr = expr.replace('amount', str(row['amount']))

        # Evaluate safely (basic arithmetic only)
        return eval(expr, {'__builtins__': None}, {})
    except Exception as e:
        raise ValueError(f"Error evaluating formula: {e}")

def main():
    if len(sys.argv) != 2:
        sys.stderr.write("Usage: python filter_records.py <database_path>\n")
        sys.exit(1)

    db_path = sys.argv[1]
    conn = sqlite3.connect(db_path)
    cursor = conn.cursor()

    # Read filter rules from stdin
    rules = []
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        try:
            column, operator, value = parse_filter_rule(line)
            rules.append((column, operator, value))
        except ValueError as e:
            sys.stderr.write(f"Error parsing filter rule: {e}\n")
            sys.exit(1)

    if not rules:
        sys.stderr.write("No filter rules provided.\n")
        sys.exit(1)

    # Build WHERE clause dynamically
    where_clauses = []
    params = []
    for column, operator, value in rules:
        if column == 'id':
            if operator == '=':
                params.append(value)
                where_clauses.append(f"id = ?")
            elif operator == '!=':
                params.append(value)
                where_clauses.append(f"id != ?")
            else:
                params.append(value)
                where_clauses.append(f"id {operator} ?")
        elif column == 'amount':
            if operator == '=':
                params.append(value)
                where_clauses.append(f"amount = ?")
            elif operator == '!=':
                params.append(value)
                where_clauses.append(f"amount != ?")
            else:
                params.append(value)
                where_clauses.append(f"amount {operator} ?")
        else:
            # For name and category, use LIKE with % for wildcards
            if operator == '=':
                params.append(f"%{value}%")
                where_clauses.append(f"{column} LIKE ?")
            else:
                # For other operators, use direct comparison (no wildcards)
                params.append(value)
                where_clauses.append(f"{column} {operator} ?")

    where_clause = " AND ".join(where_clauses)
    query = f"SELECT id, name, category, amount, formula FROM records WHERE {where_clause} ORDER BY id ASC"

    cursor.execute(query, params)
    rows = cursor.fetchall()

    for row in rows:
        try:
            result = evaluate_expression(row[4], dict(zip(['id', 'name', 'category', 'amount'], row[:4])))
            print(f"{row[0]},{row[1]},{result}")
        except Exception as e:
            sys.stderr.write(f"Error processing row: {e}\n")
            continue

    conn.close()

if __name__ == "__main__":
    main()
